function executeSkill(context) {
    var source=context.piece, world=battle.extensions.adventureWorld, plan=world.plans && world.plans[0];
    if(!plan || plan.sourceId!==source.instanceId || plan.kind!=='attack' || source.x!==plan.origin.x || source.y!==plan.origin.y) return {success:false,message:'预告计划已失效'};
    for(var i=0;i<plan.cells.length;i++) {
      var cell=plan.cells[i],tile=battle.map.tiles.find(function(t){return t.x===cell.x&&t.y===cell.y;});
      if(!tile || tile.props.bulletPassable===false)break;
      var target=battle.pieces.find(function(p){return p.currentHp>0&&p.x===cell.x&&p.y===cell.y;});
      if(target) {
        if(target.ownerPlayerId!==source.ownerPlayerId) dealDamage(source,target,source.attack,'physical',battle,context.skill.id);
        return {success:true,message:source.name+'执行抓击'};
      }
    }
    return {success:true,message:source.name+'的抓击落空'};
  }
